const BELAVADOS_SPACE = {
  planet: {
    radiusKm: 6371.0088,
    terrainElevationUnits: "meters",
    bathymetryIsNegative: true
  },
  distance: {
    auKm: 149597870.7,
    lightYearKm: 9460730472580.8,
    exosphereAltitudeKm: 10000,
    chandratescuSelenesOrbitKm: 386200,
    mictlindraNannaraRelativeOrbitKm: 41600
  },
  moonlet: {
    name: "Mictlindra-Nannara",
    diameterKm: 544.3,
    diameterMi: 338,
    sizeScaleFromOldCanon: 1 / 3,
    orbitInclinationDeg: 125,
    retrograde: true,
    angularDirection: -1
  },
  renderScale: {
    planetRadiusUnits: 1000,
    starSphereUnits: 260000,
    nebulaSphereUnits: 270000,
    moonOrbitUnits: 60618,
    exosphereRadiusUnits: 2570
  }
};

function raDecToUnitVector(raDeg, decDeg) {
  const ra = THREE.MathUtils.degToRad(raDeg);
  const dec = THREE.MathUtils.degToRad(decDeg);
  return new THREE.Vector3(
    Math.cos(dec) * Math.cos(ra),
    Math.sin(dec),
    Math.cos(dec) * Math.sin(ra)
  ).normalize();
}

function fixedStarRenderPosition(star) {
  // star.distanceLy remains metadata; RA/Dec controls visible sky position.
  return raDecToUnitVector(star.raDeg, star.decDeg)
    .multiplyScalar(BELAVADOS_SPACE.renderScale.starSphereUnits);
}

function realKmFromLightYears(lightYears) {
  return lightYears * BELAVADOS_SPACE.distance.lightYearKm;
}

function moonletOrbitAngle(phaseFraction) {
  // Negative angular direction makes the moonlet retrograde around Chandratecu-Seleneš.
  return phaseFraction * Math.PI * 2 * BELAVADOS_SPACE.moonlet.angularDirection;
}

// Eirsuneth expanded constellation-layer path constants
const AU_PER_LY = 63241.077084266290;
const qAU = 2.08;
const targetConstellation = "Nephthysra's Mirror";
const targetRole = "fourth_to_last_constellation_by_distance_atlas";
const Q_LY = 54000;
const Q_AU = Q_LY * AU_PER_LY; // 3415018162.550380
const aAU = (qAU + Q_AU) / 2; // 1707509082.315190
const e = (Q_AU - qAU) / (Q_AU + qAU); // 0.999999998782
const bAU = Math.sqrt(qAU * Q_AU); // 84280.708220
const inclinationDeg = 18;
const P_years_trueScale = Math.pow(aAU, 1.5); // 7.055772e+13
const P_days_trueScale = P_years_trueScale * 330.15; // 2.329463e+16

// Use this for lore/deep-space zoom. For normal gameplay, drive a normalized
// 0..1 orbit fraction with time compression and map radius logarithmically.
function cometRadiusFromE(E) { return aAU * (1 - e * Math.cos(E)); }
function cometZFromTrueAnomaly(r, nuRad) { return r * Math.sin(nuRad) * Math.sin(inclinationDeg * Math.PI / 180); }
function displayRadiusAU(rAU) { return Math.log10(1 + rAU); }

